<?php require __DIR__.'/../koneksi.php';$n=(int)$koneksi->query("SELECT COUNT(*) AS n FROM users WHERE role='admin'")->fetch_assoc()['n'];if($n>0){http_response_code(403);exit('Admin sudah ada. Hapus file setup_admin.php setelah digunakan.');}$error='';$done=false;if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$username=trim($_POST['username']??'');$password=$_POST['password']??'';if(strlen($username)<4||strlen($password)<10){$error='Username minimal 4 karakter, password minimal 10 karakter.';}else{$hash=password_hash($password,PASSWORD_DEFAULT);$st=$koneksi->prepare("INSERT INTO users(nama,username,password_hash,role) VALUES('Administrator',?,?,'admin')");$st->bind_param('ss',$username,$hash);$st->execute();$done=true;}}$base='../';$page_title='Buat Admin';require __DIR__.'/../partials/header.php';?><main class="container py-5" style="max-width:500px"><div class="soft-card p-4"><h3>Setup Admin (sekali)</h3><?php if($done):?><div class="alert alert-success">Akun dibuat. Hapus file admin/setup_admin.php, lalu <a href="login.php">login</a>.</div><?php else:?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Username</label><input class="form-control mb-3" name="username" required minlength="4"><label>Password (min. 10 karakter)</label><input class="form-control mb-3" type="password" name="password" minlength="10" required><button class="btn btn-pink">Buat Akun</button></form><?php endif;?></div></main><?php require __DIR__.'/../partials/footer.php';?>
